# Function to calculate C(2^a) based on the derived formula for verification
def calculate_C_2a(a):
    if a == 1:
        return 1
    if a == 2:
        return 2
    # For a >= 3, C(2^a) = 2a - 2
    return 2 * a - 2

# Test small values
test_a = [1, 2, 3, 4, 5, 6]
results = {}
for a in test_a:
    C_ma = calculate_C_2a(a)
    results[a] = C_ma

print("a values: ", test_a)
print("C(2^a) values: ", results)
